// server/controllers/publicBusinessController.js
const Business = require("../models/Business");
const Booking = require("../models/Booking");
const Review = require("../models/Review");

/**
 * Helper: attach averageRating + reviewCount to a list of businesses
 */
async function attachRatings(businesses) {
  if (!businesses.length) return [];

  const businessIds = businesses.map((b) => b._id);

  const ratingStats = await Review.aggregate([
    { $match: { business: { $in: businessIds } } },
    {
      $group: {
        _id: "$business",
        averageRating: { $avg: "$rating" },
        reviewCount: { $sum: 1 },
      },
    },
  ]);

  const ratingMap = new Map();
  ratingStats.forEach((stat) => {
    ratingMap.set(String(stat._id), {
      averageRating: stat.averageRating,
      reviewCount: stat.reviewCount,
    });
  });

  return businesses.map((b) => {
    const stats = ratingMap.get(String(b._id)) || {};
    const avg = stats.averageRating || 0;

    return {
      ...b,
      averageRating: Number(avg.toFixed(1)) || 0,
      reviewCount: stats.reviewCount || 0,
    };
  });
}

/**
 * GET /api/public/businesses
 * All businesses for homepage (used for For Her / For Him)
 */
exports.getAllBusinesses = async (req, res) => {
  try {
    const businesses = await Business.find({}).lean();
    const withRatings = await attachRatings(businesses);
    res.json(withRatings);
  } catch (err) {
    console.error("Error in getAllBusinesses:", err);
    res.status(500).json({ message: "Server error" });
  }
};

/**
 * GET /api/public/businesses/:id
 * Single business details
 */
exports.getBusinessDetails = async (req, res) => {
  try {
    const business = await Business.findById(req.params.id).lean();

    if (!business) {
      return res.status(404).json({ message: "Business not found" });
    }

    const [withRating] = await attachRatings([business]);
    res.json(withRating || business);
  } catch (err) {
    console.error("Error in getBusinessDetails:", err);
    res.status(500).json({ message: "Server error" });
  }
};

/**
 * GET /api/public/businesses/highest-rated
 * Top 8 salons by average rating
 */
exports.getHighestRatedBusinesses = async (req, res) => {
  try {
    const businesses = await Business.find({}).lean();
    let withRatings = await attachRatings(businesses);

    // Sort by highest rating, then by most reviews
    withRatings.sort((a, b) => {
      const diff = (b.averageRating || 0) - (a.averageRating || 0);
      if (diff !== 0) return diff;
      return (b.reviewCount || 0) - (a.reviewCount || 0);
    });

    res.json(withRatings.slice(0, 8));
  } catch (err) {
    console.error("Error in getHighestRatedBusinesses:", err);
    res.status(500).json({ message: "Server error" });
  }
};

/**
 * GET /api/public/businesses/trending
 * Top 8 salons with the most bookings in the last 30 days
 */
exports.getTrendingBusinesses = async (req, res) => {
  try {
    const now = new Date();
    const oneMonthAgo = new Date();
    oneMonthAgo.setMonth(now.getMonth() - 1);

    // Aggregate bookings per business in last month
    const bookingAgg = await Booking.aggregate([
      {
        $match: {
          startTime: { $gte: oneMonthAgo, $lte: now },
        },
      },
      {
        $group: {
          _id: "$business",
          bookingsCount: { $sum: 1 },
        },
      },
      { $sort: { bookingsCount: -1 } },
      { $limit: 8 },
    ]);

    if (!bookingAgg.length) {
      return res.json([]);
    }

    const businessIds = bookingAgg.map((b) => b._id);
    const businesses = await Business.find({ _id: { $in: businessIds } }).lean();

    // Sync bookingsCount with businesses
    const bookingsMap = new Map();
    bookingAgg.forEach((b) => {
      bookingsMap.set(String(b._id), b.bookingsCount);
    });

    let withRatings = await attachRatings(businesses);

    // Attach bookingsCount & keep order by bookingsCount desc
    withRatings = withRatings.map((b) => ({
      ...b,
      bookingsCount: bookingsMap.get(String(b._id)) || 0,
    }));

    withRatings.sort((a, b) => (b.bookingsCount || 0) - (a.bookingsCount || 0));

    res.json(withRatings);
  } catch (err) {
    console.error("Error in getTrendingBusinesses:", err);
    res.status(500).json({ message: "Server error" });
  }
};
